func dependsOn(a *ast.AnnotationsRef) []string {
	if a == nil {
		return []string{}
	}

	dependsOn, ok := a.Annotations.Custom["depends_on"]

	if !ok {
		return []string{}
	}

	switch d := dependsOn.(type) {
	case []any:
		ret := make([]string, 0, len(d))
		for _, v := range d {
			ret = append(ret, fmt.Sprint(v))
		}
		return ret
	default:
		return []string{fmt.Sprint(d)}
	}
}

