func ociImageFiles(bctx rego.BuiltinContext, refTerm *ast.Term, pathsTerm *ast.Term) (*ast.Term, error) {
	log := log.WithField("rego", ociImageFilesName)
	uri, ok := refTerm.Value.(ast.String)
	if !ok {
